//! Exact ARIA metadata reaches supported displayed HTML and transfer consumers.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><p id=target></p><div id=mount></div><input id=field value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://html-aria-units.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn html_aria_domstring_displayed_producers_attrs_observers_and_literal_selector_separation(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var source=document.getElementById('target'),descriptor=Object.getOwnPropertyDescriptor(Element.prototype,'ariaLabel');source.ariaLabel='A\ud800z';var a=source.getAttributeNode('aria-label'),watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,attributeOldValue:true});source.setAttribute('aria-label','B\udfffz');source.setAttributeNS(null,'aria-label','C\ud800z');a.value='D\udfffz';a.nodeValue='E\ud800z';a.textContent='F\udfffz';descriptor.set.call(source,'G\ud800z');if(source.ariaLabel!=='G\ud800z'||source.getAttribute('aria-label')!==source.ariaLabel||a!==source.getAttributeNode('aria-label')||a.value!==source.ariaLabel||source.matches('[aria-label="G�z"]')||document.querySelectorAll('[aria-label]')[0]!==source)throw 'exact displayed native ARIA metadata';var records=watch.takeRecords();if(records.length!==6||records[0].oldValue!=='A\ud800z'||records[5].oldValue!=='F\udfffz'||records[5].attributeName!=='aria-label'||records[5].attributeNamespace!==null||records[5].target!==source)throw 'exact native records';source.ariaLabel=null;if(source.ariaLabel!==null||a.ownerElement!==null||a.value!=='G\ud800z')throw 'nullable displayed detach';"#);}
#[test]
fn html_aria_domstring_import_copies_exact_native_values_without_source_or_author_aliases(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('owner'),source=owner.createElement('p');source.ariaLabel='A\ud800z';source.role='R\udfffz';source.textContent='copied';var descriptor=Object.getOwnPropertyDescriptor(Element.prototype,'ariaLabel'),hits=0;Object.defineProperty(source,'ariaLabel',{get:function(){hits++;throw 'author getter';},configurable:true});var a=source.getAttributeNode('aria-label'),copy=document.importNode(source,true);document.getElementById('mount').appendChild(copy);if(hits||copy===source||copy.ownerDocument!==document||source.ownerDocument!==owner||copy.ariaLabel!=='A\ud800z'||copy.role!=='R\udfffz'||copy.getAttributeNode('aria-label')===a||copy.matches('[aria-label="A�z"]'))throw 'exact independent native import';copy.ariaLabel='fresh';if(descriptor.get.call(source)!=='A\ud800z'||a.value!=='A\ud800z'||copy.ariaLabel!=='fresh')throw 'independent source records';"#);}
#[test]
fn html_aria_domstring_parked_and_cloned_template_promotion_keep_attr_identity_and_queries(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var t=document.createElement('template');t.innerHTML='<p>promoted</p>';var source=t.content.firstChild;source.ariaLabel='A\ud800z';source.role='R\udfffz';var a=source.getAttributeNode('aria-label'),owner=source.ownerDocument,watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,attributeOldValue:true});var clone=t.cloneNode(true),copy=clone.content.firstChild;copy.ariaLabel='B\udfffz';document.getElementById('mount').appendChild(t.content);if(source.ownerDocument!==document||a.ownerDocument!==document||source.getAttributeNode('aria-label')!==a||source.ariaLabel!=='A\ud800z'||source.role!=='R\udfffz'||copy.ariaLabel!=='B\udfffz'||source.matches('[aria-label="A�z"]')||document.querySelectorAll('[aria-label]')[0]!==source||watch.takeRecords().length)throw 'native promotion exact identity';source.ariaLabel='C\ud800z';var records=watch.takeRecords();if(records.length!==1||records[0].oldValue!=='A\ud800z'||records[0].target!==source||a.value!==source.ariaLabel||copy.ariaLabel!=='B\udfffz')throw 'promoted exact native update';"#);}

#[test]
fn html_aria_domstring_registered_mapping_producers_and_native_control_value_stay_distinct(){let(mut d,mut f,mut p)=fixture();let field=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("field")).unwrap();f.script_set_value(field,"edited").unwrap();let pairs=crate::javascript::aria_reflection_interface::ATTRIBUTES.iter().map(|(property,key,_,_)|format!("[{property:?},{key:?}]")).collect::<Vec<_>>().join(",");run(&mut d,&mut f,&mut p,&format!(r#"var source=document.getElementById('target'),pairs=[{pairs}];for(var pair of pairs){{var property=pair[0],name=pair[1];source[property]='A\ud800z';var a=source.getAttributeNodeNS(null,name);if(source[property]!=='A\ud800z'||a.value!==source[property]||source[property]==='A�z')throw 'registered HTML nullable producer';a.value='B\udfffz';if(source[property]!=='B\udfffz'||source.getAttributeNodeNS(null,name)!==a)throw 'registered attached native Attr';source[property]=null;if(source[property]!==null||a.ownerElement!==null)throw 'registered native nullable removal';}}var field=document.getElementById('field');field.ariaLabel='C\ud800z';field.role='R\udfffz';if(field.value!=='edited'||field.ariaLabel!=='C\ud800z'||field.role!=='R\udfffz')throw 'native control state independent';"#));assert_eq!(f.controls[&field].value.text().as_str(),"edited");}
#[test]
fn html_aria_domstring_foreign_unknown_and_child_writes_keep_real_guards(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var source=document.getElementById('target'),shape=document.createElementNS('http://www.w3.org/2000/svg','svg'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);source.ariaLabel='seed';shape.ariaLabel='svg';var child=frame.contentDocument.body,descriptor=Object.getOwnPropertyDescriptor(Element.prototype,'ariaLabel'),calls=0;"#);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for expression in [r#"source.setAttributeNS('urn:attribute','aria-label','A\ud800z');"#,r#"source.setAttribute('aria-unknown','A\ud800z');"#,r#"shape.ariaLabel='A\ud800z';"#]{p.begin_job();let error=p.runtime.execute(expression,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("Unpaired attribute"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.begin_job();let error=p.runtime.execute("descriptor.set.call(child,{toString:function(){calls++;return 'bad';}});",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("child ARIA"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"if(calls||source.ariaLabel!=='seed'||shape.ariaLabel!=='svg')throw 'guard before publication and conversion';source.ariaLabel='A\\ud800z';if(source.ariaLabel!=='A\\ud800z')throw 'fresh native recovery';");}
#[test]
fn html_aria_domstring_import_and_promotion_resource_refusal_is_atomic_and_recovers(){
 for promote in [false,true]{let(mut d,mut forms,mut page)=fixture();run(&mut d,&mut forms,&mut page,r#"var owner=document.implementation.createHTMLDocument('source'),source=owner.createElement('div'),names=['aria-label','role'];owner.body.appendChild(source);var t=document.createElement('template');t.innerHTML='<span aria-label=seed role=seed>held</span>';var parked=t.content.firstChild,oldOwner=parked.ownerDocument,attrs=[];for(var i=0;i<names.length;i++){source.setAttribute(names[i],'long A\ud800z');var a=parked.getAttributeNode(names[i]);a.value='long B\udfffz';attrs.push(a);}var mount=document.getElementById('mount'),watch=new MutationObserver(function(){});watch.observe(mount,{childList:true});"#);page.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(page.state.retained,page.state.dom_commits,page.state.attributes.len());let limit=page.state.retained_limit;
  for mode in 0..3{page.begin_job();match mode{0=>page.state.host_work=0,1=>page.state.copy_work=0,_=>page.state.retained_limit=0};let source=if promote{"mount.appendChild(t.content);"}else{"document.importNode(source,true);"};let error=page.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut forms,state:&mut page.state}).unwrap_err();assert!(error.contains("work")||error.contains("allowance")||error.contains("limit"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((page.state.retained,page.state.dom_commits,page.state.attributes.len()),state);page.state.retained_limit=limit;}
  page.begin_job();run(&mut d,&mut forms,&mut page,r#"if(source.parentNode!==owner.body||parked.parentNode!==t.content||parked.ownerDocument!==oldOwner||watch.takeRecords().length||mount.childNodes.length)throw 'refusal publication';for(var i=0;i<names.length;i++)if(source.getAttribute(names[i])!=='long A\ud800z'||parked.getAttributeNode(names[i])!==attrs[i]||attrs[i].ownerDocument!==oldOwner||attrs[i].value!=='long B\udfffz')throw 'refused attributes';var copy=document.importNode(source,true);mount.appendChild(copy);mount.appendChild(t.content);if(copy.ariaLabel!=='long A\ud800z'||parked.role!=='long B\udfffz'||parked.ariaLabel!=='long B\udfffz'||attrs[0].ownerDocument!==document)throw 'fresh metadata recovery';"#);
 }
}
#[test]
fn html_aria_domstring_foreign_namespaced_and_active_import_guards_remain_atomic(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=document.implementation.createHTMLDocument('source'),foreign=owner.createElementNS('http://www.w3.org/2000/svg','g'),qualified=owner.createElement('span'),active=owner.createElement('a');foreign.setAttribute('aria-label','A\ud800z');qualified.setAttributeNS('urn:attr','aria-label','A\ud800z');active.setAttribute('href','A\ud800z');
"#);p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());for source in ["document.importNode(foreign,true);","document.importNode(qualified,true);","document.importNode(active,true);"]{p.begin_job();assert!(p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err(),"{source}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);}run(&mut d,&mut f,&mut p,r#"if(foreign.ownerDocument!==owner||foreign.getAttribute('aria-label')!=='A\ud800z'||qualified.getAttributeNS('urn:attr','aria-label')!=='A\ud800z'||active.getAttribute('href')!=='A\ud800z')throw 'protected metadata';var good=owner.createElement('span');good.ariaLabel='B\udfffz';var copy=document.importNode(good,true);if(copy.ariaLabel!==good.ariaLabel||copy.ownerDocument!==document)throw 'fresh recovery';"#);}
#[test]
fn html_aria_domstring_native_refusal_cancellation_and_recovery_preserve_both_attributes(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var source=document.getElementById('target');source.setAttributeNS('urn:attribute','aria-label','foreign');source.ariaLabel='A\ud800z';var a=source.getAttributeNodeNS(null,'aria-label'),foreign=source.getAttributeNodeNS('urn:attribute','aria-label'),watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,attributeOldValue:true});"#);let before=(d.nodes.len(),p.state.attributes.len(),p.state.dom_commits,p.state.retained);let retained=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;
for mode in 0..5{for expression in [r#"source.ariaLabel='longB\udfffz';"#,"source.ariaLabel=null;"]{if mode==3&&!expression.contains("long"){continue;}p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=0,3=>p.state.limits.host.string_bytes=4,_=>p.state.execution_deadline=Some(Instant::now())};let error=p.runtime.execute(expression,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("mode {mode}, {expression}"));assert!(error.contains("work")||error.contains("allowance")||error.contains("bound")||error.contains("limit"),"{error}");assert_eq!((d.nodes.len(),p.state.attributes.len(),p.state.dom_commits,p.state.retained),before);p.state.retained_limit=retained;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;}}
p.begin_job();run(&mut d,&mut f,&mut p,r#"if(source.ariaLabel!=='A\ud800z'||a.value!==source.ariaLabel||foreign.value!=='foreign'||watch.takeRecords().length)throw 'refusal preserves exact records';source.ariaLabel='B\udfffz';source.ariaLabel=null;var records=watch.takeRecords();if(source.ariaLabel!==null||a.ownerElement!==null||a.value!=='B\udfffz'||foreign.ownerElement!==source||foreign.value!=='foreign'||records.length!==2||records[0].oldValue!=='A\ud800z'||records[1].oldValue!=='B\udfffz')throw 'fresh nullable recovery';"#);}

#[test]
fn html_aria_domstring_native_control_import_preserves_actual_value_and_metadata(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('source'),source=owner.createElement('input');source.setAttribute('name','q');source.setAttribute('value','ready');source.ariaLabel='A\ud800z';source.role='R\udfffz';var copy=document.importNode(source,true);document.getElementById('mount').appendChild(copy);if(copy.value!=='ready'||copy.name!=='q'||copy.form!==null||copy.ariaLabel!=='A\ud800z'||copy.role!=='R\udfffz'||copy.matches('[aria-label="A�z"]'))throw 'native imported control';copy.value='edited';copy.ariaLabel='B\udfffz';if(copy.value!=='edited'||source.getAttribute('value')!=='ready'||source.ariaLabel!=='A\ud800z'||copy.ariaLabel!=='B\udfffz')throw 'independent native metadata and control state';"#);}
